- Example snippet (in doc):
  decoder := streamdecode.NewJSONChunkDecoder[FunctionArgs]()
  sink := client.Stream(ctx, request).WithDecoder(decoder)
  for {
    args, err := sink.Next(ctx)
    if err == io.EOF { break }
    if err != nil { log.Error(err); continue }
    handleFunctionCall(args)
  }
